def relative_minor(key):
    """Return the relative minor of a major key.

    Example:
    >>> relative_minor('C')
    'a'
    """
    for couple in keys:
        if key == couple[0]:
            return couple[1]
    raise NoteFormatError("'%s' is not a major key" % key)

def is_valid_key(key):
    """Return True if key is in a recognized format. False if not."""
    for couple in keys:
        if key in couple:
            return True
    return False
